package com.example.swiftgrab.data.cookies

import android.content.Context
import android.util.Log
import java.io.File

object CookieStorageManager {

    private const val TAG = "CookieStorageManager"
    private const val COOKIES_DIR_NAME = "cookies"
    private const val X_COOKIES_FILE_NAME = "x_cookies.txt"

    private const val NETSCAPE_HEADER =
        "# Netscape HTTP Cookie File\n# This file is generated by SwiftGrab. Do not edit.\n\n"

    /**
     * Checks if a valid auth_token cookie exists in the stored X cookies.
     */
    fun hasValidXCookies(context: Context): Boolean {
        val file = getXCookiesFile(context) ?: return false
        if (!file.exists() || file.length() == 0L) return false
        val content = try {
            file.readText()
        } catch (_: Exception) {
            return false
        }
        return content.contains("auth_token")
    }

    /**
     * Returns the File pointer to x_cookies.txt if it exists and has content, otherwise null.
     */
    fun getXCookiesFile(context: Context): File? {
        val dir = File(context.filesDir, COOKIES_DIR_NAME)
        val file = File(dir, X_COOKIES_FILE_NAME)
        return if (file.exists() && file.length() > 0L) file else null
    }

    /**
     * Converts a raw cookie string (from Android CookieManager) into Netscape format
     * and saves it to internal private storage.
     */
    fun saveXCookies(context: Context, rawCookieHeader: String): Boolean {
        if (rawCookieHeader.isBlank()) return false

        try {
            val netscapeContent = parseToNetscape(rawCookieHeader)
            if (netscapeContent.isBlank()) return false

            val dir = File(context.filesDir, COOKIES_DIR_NAME)
            if (!dir.exists()) {
                dir.mkdirs()
            }
            val file = File(dir, X_COOKIES_FILE_NAME)
            file.writeText(netscapeContent)
            Log.i(TAG, "Successfully saved X/Twitter Netscape cookies to ${file.absolutePath}")
            return true
        } catch (e: Exception) {
            Log.e(TAG, "Failed to save X/Twitter cookies", e)
            return false
        }
    }

    /**
     * Clears stored X cookies file.
     */
    fun clearXCookies(context: Context) {
        try {
            val file = File(File(context.filesDir, COOKIES_DIR_NAME), X_COOKIES_FILE_NAME)
            if (file.exists()) {
                file.delete()
                Log.i(TAG, "Deleted X cookies file")
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to delete X cookies file", e)
        }
    }

    /**
     * Converts a raw cookie header string ("key=value; key2=value2") into Netscape format
     * targeting both .x.com and .twitter.com.
     */
    fun parseToNetscape(rawCookieHeader: String): String {
        val pairs = rawCookieHeader.split(";").map { it.trim() }.filter { it.isNotEmpty() }
        if (pairs.isEmpty()) return ""

        val sb = StringBuilder(NETSCAPE_HEADER)
        val expiryTimestamp = "2147483647" // 2038 standard Netscape expiry timestamp

        val domains = listOf(".x.com", ".twitter.com")

        for (pair in pairs) {
            val equalIndex = pair.indexOf('=')
            if (equalIndex <= 0) continue

            val name = pair.substring(0, equalIndex).trim()
            val value = pair.substring(equalIndex + 1).trim()

            if (name.isEmpty() || value.isEmpty()) continue

            for (domain in domains) {
                // Netscape 7 columns: domain, includeSubdomains, path, secure, expiry, name, value
                sb.append(domain).append("\t")
                sb.append("TRUE").append("\t")
                sb.append("/").append("\t")
                sb.append("TRUE").append("\t")
                sb.append(expiryTimestamp).append("\t")
                sb.append(name).append("\t")
                sb.append(value).append("\n")
            }
        }

        return sb.toString()
    }

    /**
     * Verifies if the cookie string contains typical authenticated session tokens.
     */
    fun containsAuthTokens(cookieString: String?): Boolean {
        if (cookieString.isNullOrBlank()) return false
        return cookieString.contains("auth_token=") || cookieString.contains("twid=")
    }
}
